/*
 * 【解题思路】合并两个有序数组（朴素解）
 * 为什么这样做：各设一个下标分别扫描A和B，谁小就放入temp，最后把temp复制回A。
 * 关键理解：i、j分别指向两段有效数据的当前最小值。
 * 关键理解：temp[k++]先写入再推进下标，不会覆盖源数组。
 * 关键理解：某数组到达末尾后，另一段直接全部复制即可。
 * 考场注意：正确且直观；如果题目特别要求原地、额外空间O(1)，则不能满足。
 */
#include <stdio.h>
#define MAXN 1000

// 朴素归并：额外申请一块临时数组，避免覆盖尚未比较的元素
void merge(int A[], int m, int B[], int n) {
    int temp[MAXN];                // 辅助空间：最多存放m+n个数
    int i = 0, j = 0, k = 0;      // i遍历A，j遍历B，k填写temp
    if (m+n > MAXN) return;       // 保护测试程序的固定容量
    // 两段都还有未处理元素时才能比较当前值，避免读取数组边界之外。
    while (i < m && j < n) {
        if (A[i] <= B[j]) temp[k++] = A[i++];
        else temp[k++] = B[j++];  // 选当前较小的数，两个相同值也能正确处理
    }
    while (i < m) temp[k++] = A[i++];  // A中剩余的元素
    while (j < n) temp[k++] = B[j++];  // B中剩余的元素
    for (i = 0; i < m+n; i++) A[i] = temp[i]; // 结果复制回A
}
int main(void) {
    int A[6] = {1,3,5,0,0,0}, B[3] = {2,4,6};
    merge(A,3,B,3);
    for (int i=0;i<6;i++) printf("%d%c",A[i],i==5?'\n':' ');
    return 0;
}

