#include <stdio.h>
typedef struct Node { int data; struct Node *next; } Node;
// 第一次求长度，第二次从头走n/2步
Node* middle(Node *head) {
    int n=0;
    for(Node *p=head;p!=NULL;p=p->next) n++; // 统计结点个数
    Node *p=head;
    for(int i=0;i<n/2;i++) p=p->next;         // 偶数时取靠后中点
    return p;                                 // 空链表时也是NULL
}
