/*
 * 【解题思路】从冒泡排序理解直接插入排序（优化解）
 * 为什么这样做：把前面部分视为已排好序。取出下一个元素key，从已排序段右端往左移动比key大的元素，再插入空位。
 * 关键理解：外层从i=1开始，因为单个元素天然有序。
 * 关键理解：保存key，再从右往左移动大于它的数，不在循环里反复交换。
 * 关键理解：循环终止时j+1恰好是key的插入位置。
 * 考场注意：近乎有序时移动次数少；408基础排序重点，考场应掌握。
 */
#include <stdio.h>
// 保持左边区间a[0..i-1]有序，把a[i]插进去
void sort(int a[],int n){
    for(int i=1;i<n;i++){
        int key=a[i];              // 保存待插入元素，防止被覆盖
        int j=i-1;
        while(j>=0 && a[j]>key){
            a[j+1]=a[j];           // 右移比key大的元素
            j--;
        }
        a[j+1]=key;                // 将key写入腾出的正确位置
    }
}
int main(void){
    int a[]={5,2,4,6,1,3};
    sort(a,6);
    for(int i=0;i<6;i++)printf("%d%c",a[i],i==5?'\n':' ');
    return 0;
}

