/*
 * 【解题思路】统计二叉树的叶子结点数（优化解）
 * 为什么这样做：先判断当前结点是不是叶子，再递归左右子树；把两次递归的返回值累加到 cnt
 * 关键理解：先序顺序：当前结点 → 左子树 → 右子树。若左右孩子都为空，当前 cnt 加 1。
 * 关键理解：CTC(NULL) 返回 0，而不是 1；空树中没有叶子结点。
 * 关键理解：递归调用不会自动共享局部 cnt，必须写 cnt += CTC(T->left) 和 cnt += CTC(T->right)。
 * 考场注意：空指针应返回 0；每次函数调用的 cnt 都是局部变量，左右子树的结果必须用 += 接收。
 */
#include <stdio.h>

typedef struct TreeNode {
    int data;
    struct TreeNode *left;
    struct TreeNode *right;
} TreeNode;

// 先序处理：先检查当前结点，再递归左右子树。
int CTC(TreeNode *T) {
    if (T == NULL) {
        return 0;  // 空树没有叶子
    }

    int cnt = 0;
    if (T->left == NULL && T->right == NULL) {
        cnt++;      // 当前结点是叶子
    }

    cnt += CTC(T->left);   // 接收左子树的叶子数
    cnt += CTC(T->right);  // 接收右子树的叶子数
    return cnt;
}

int main(void) {
    TreeNode n4 = {4, NULL, NULL};
    TreeNode n2 = {2, &n4, NULL};
    TreeNode n3 = {3, NULL, NULL};
    TreeNode n1 = {1, &n2, &n3};

    printf("%d\n", CTC(&n1));  // 输出 2
    return 0;
}

