/*
 * 【解题思路】无序数组中寻找第k大元素（优化解）
 * 为什么这样做：以末元素为枢轴，把≥枢轴的数放左边；只在含目标下标k-1的一侧继续。
 * 关键理解：划分后枢轴的下标i已确定，不必再参与排序。
 * 关键理解：若i>k-1，只需左区间；否则只需右区间。
 * 关键理解：平均处理n+n/2+…=O(n)，极端可能O(n²)。
 * 考场注意：固定枢轴可能退化，不能把平均复杂度当最坏。
 */
#include <stdio.h>
int kth_select(int a[],int n,int k){
    int left=0,right=n-1,target=k-1;
    // 闭区间两端均可能包含目标，因此相等时仍须检查最后一个候选位置。
    while(left<=right){
        int pivot=a[right],i=left;
        for(int j=left;j<right;j++){
            if(a[j]>=pivot){                 // 大的数移到左侧
                int t=a[i];a[i]=a[j];a[j]=t;
                i++;
            }
        }
        int t=a[i];a[i]=a[right];a[right]=t; // 枢轴落在最终排名i
        if(i==target)return a[i];
        if(i>target)right=i-1;             // 只保留左侧
        else left=i+1;                    // 只保留右侧
    }
    return 0;                              // 题目保证k合法
}
int main(void){
    int a[]={3,2,1,5,6,4};
    printf("%d\n",kth_select(a,6,2));
    return 0;
}

