int eval(int *i){
    char *s=t[(*i)--];
    if(s[1]=='\0'&&(s[0]=='+'||s[0]=='-'||
       s[0]=='*'||s[0]=='/')){
        int b=eval(i),a=eval(i); // 先读右操作数
        if(s[0]=='+') return a+b;
        if(s[0]=='-') return a-b;
        if(s[0]=='*') return a*b;
        return a/b;
    }
    return atoi(s);
}
int main(void){
    int i=4;
    printf("%d\n",eval(&i)); // (2+1)*3=9
    return 0;
}

