#define N 5

int a[N] = {5, 2, 4, 1, 3};
int temp[N];

void merge(int l, int m, int r) {
    int i = l, j = m + 1, k = l;
    // 两段各自有序，较小的头元素就是剩余元素中的最小值。
    while (i <= m && j <= r) {
        // 相等时取左边，保留原有先后次序（稳定排序）。
        temp[k++] = a[i] <= a[j] ? a[i++] : a[j++];
    }
    // 一边耗尽后，另一边剩余元素已经有序，直接复制。
    while (i <= m) temp[k++] = a[i++];
    while (j <= r) temp[k++] = a[j++];
    for (int p = l; p <= r; p++) a[p] = temp[p];
}

void mergeSort(int l, int r) {
    // 单元素或空区间天然有序，必须停止递归。
    if (l >= r) return;
    int m = l + (r - l) / 2;
    mergeSort(l, m);
    mergeSort(m + 1, r);
    merge(l, m, r);
}

