int valid(Node *p, long long low, long long high) {
    if (p == NULL) return 1; // 空树满足约束

    if (p->val <= low || p->val >= high)
        return 0; // 越界立即失败，禁止重复值

    // 左子树上界变为当前值；右子树下界变为当前值
    return valid(p->left, low, p->val) &&
           valid(p->right, p->val, high);
}

int main(void) {
    int ok = valid(&root, LLONG_MIN, LLONG_MAX);
    printf("%d\n", ok); // 输出 0
    return 0;
}

