            lps[i++] = ++len;       // 字符相同，公共前后缀再延长一位。
        } else if (len > 0) {
            len = lps[len - 1];     // 缩短候选前后缀，i不动以便重试。
        } else {
            lps[i++] = 0;           // len为0仍失配，不存在非空公共前后缀。
        }
    }

    // 扫描主串：失配时优先回退模式串下标，不回退主串下标。
    for (int i = 0, j = 0; i < n; ) {
        if (text[i] == pattern[j]) {
            i++;
            j++;
            if (j == m) {
                answer = i - m;     // 已匹配m个字符，起点为i-m。
                break;              // 题目只要求第一次出现的位置。
            }
        } else if (j > 0) {
            j = lps[j - 1];         // 保留已匹配前后缀，继续比较当前text[i]。
        } else {
            i++;                    // j为0仍失配，当前主串字符不可能作为匹配起点。
        }
    }
    printf("%d\n", answer);
    return 0;                       // 正常完成匹配过程。
}

