/*
 * 小根堆优化哈夫曼构造。
 * push把新权值上滤，popMin删除堆顶并下滤。
 * 每次合并只需两次弹出和一次插入。
 */
#include <stdio.h>

#define MAXN 1000
long long heap[2 * MAXN];
int heapSize = 0;

void push(long long x) {
    int i = ++heapSize;
    while (i > 1 && heap[i / 2] > x) {
        heap[i] = heap[i / 2];
        i /= 2;
    }
    heap[i] = x;
}

long long popMin(void) {
    long long result = heap[1];
    long long last = heap[heapSize--];
    int i = 1;

    // 用末尾元素填补堆顶，再向下调整
    while (i * 2 <= heapSize) {
        int child = i * 2;
        if (child + 1 <= heapSize && heap[child + 1] < heap[child])
            child++;
        if (heap[child] >= last)
            break;
        heap[i] = heap[child];
        i = child;
    }
    heap[i] = last;
    return result;
}

int main(void) {
    int input[6] = {5, 9, 12, 13, 16, 45};
    int n = 6;
    long long wpl = 0;

    // 初始森林中的每个叶权值都进入小根堆
    for (int i = 0; i < n; i++)
        push(input[i]);

    while (heapSize > 1) {
        long long a = popMin();
        long long b = popMin();
        long long sum = a + b;

        wpl += sum;
        push(sum); // 合并结点重新加入森林
    }

    printf("%lld\n", wpl); // 224
    return 0;
}

