/*
 * 优化法：拓扑排序 + 正向ve + 逆向vl。
 * ve[v]：事件v最早发生时间，按拓扑序取最大值。
 * vl[u]：事件u最迟发生时间，按逆拓扑序取最小值。
 * 活动u->v为关键活动，当 ve[u] == vl[v] - w[u][v]。
 */
#include <stdio.h>
#define N 6
#define M 8

int main(void) {
    int from[M] = {0, 0, 1, 1, 2, 2, 3, 4};
    int to[M]   = {1, 2, 3, 4, 3, 4, 5, 5};
    int dur[M]  = {3, 2, 2, 3, 4, 2, 3, 2};
    int w[N][N] = {0};            // 邻接矩阵保存活动工期
    int indeg[N] = {0};

    for (int e = 0; e < M; e++) {
        w[from[e]][to[e]] = dur[e];
        indeg[to[e]]++;           // 统计每个事件的入度
    }

    int q[N], topo[N];
    int front = 0, rear = 0, k = 0;
    for (int i = 0; i < N; i++)
        if (indeg[i] == 0) q[rear++] = i;

    // Kahn拓扑排序；出队事件的ve值已由所有前驱确定
    int ve[N] = {0};
    while (front < rear) {
        int u = q[front++];
        topo[k++] = u;
        for (int v = 0; v < N; v++) {
            if (w[u][v] > 0) {
                if (ve[v] < ve[u] + w[u][v])
                    ve[v] = ve[u] + w[u][v]; // 正向取最大
                indeg[v]--;
                if (indeg[v] == 0) q[rear++] = v;
            }
        }
    }

    if (k != N) {                 // 有环就不是合法AOE网
        printf("-1\n");
        return 0;
    }

    int vl[N];
    for (int i = 0; i < N; i++) vl[i] = ve[N - 1];

    // 逆拓扑序：所有后继的vl已知，当前事件取最小
    for (int i = k - 1; i >= 0; i--) {
        int u = topo[i];
        for (int v = 0; v < N; v++) {
            if (w[u][v] > 0 && vl[u] > vl[v] - w[u][v])
                vl[u] = vl[v] - w[u][v];
        }
    }

    printf("%d\n", ve[N - 1]);    // 项目总工期

    // 沿“关键活动”输出一条关键路径
    int u = 0;
    printf("%d", u + 1);
    while (u != N - 1) {
        int found = 0;
        for (int v = 0; v < N; v++) {
            if (w[u][v] > 0 &&
                ve[u] == vl[v] - w[u][v] &&
                ve[v] == ve[u] + w[u][v]) {
                u = v;
                printf("->%d", u + 1);
                found = 1;
                break;
            }
        }
        if (!found) return 1;     // 合法样例中应能走到汇点
    }
    printf("\n");
    return 0;
}

