/*
 * 快速排序：Hoare双向扫描。
 * 取区间中间位置的值作pivot，左右指针向中间扫描并交换错位元素。
 * 划分结束后递归处理两个仍可能无序的子区间。
 */
#include <stdio.h>
#define MAX 100

void quickSort(int a[], int low, int high) {
    if (low >= high) {
        return; /* 区间至多一个元素，天然有序，无需再划分。 */
    }

    int i = low, j = high;
    int pivot = a[low + (high - low) / 2]; /* 复制枢轴值，交换数组元素不会改变比较基准。 */

    while (i <= j) {
        while (a[i] < pivot) {
            i++; /* 小于枢轴的元素已在左侧，继续寻找左边错放的大元素。 */
        }
        while (a[j] > pivot) {
            j--; /* 大于枢轴的元素已在右侧，继续寻找右边错放的小元素。 */
        }
        if (i <= j) {
            int temp = a[i];
            a[i] = a[j];
            a[j] = temp; /* 交换左右错位元素；相等时也交换以保证指针前进。 */
            i++;
            j--; /* 即使两值等于pivot也必须移动，避免重复值导致死循环。 */
        }
    }

    if (low < j) {
        quickSort(a, low, j); /* 左区间至少有两个元素时才递归。 */
    }
    if (i < high) {
        quickSort(a, i, high); /* 右区间至少有两个元素时才递归。 */
    }
}

int main(void) {
    int n, a[MAX];
    if (scanf("%d", &n) != 1 || n < 1 || n > MAX) {
        return 1; /* 输入长度非法，避免数组越界或空区间访问。 */
    }
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1) {
            return 1; /* 读入不完整时立即退出，防止排序未初始化元素。 */
        }
    }

    quickSort(a, 0, n - 1);
    for (int i = 0; i < n; i++) {
        printf("%d%c", a[i], i == n - 1 ? '\n' : ' ');
    }
    return 0;
}

