void dfs(int u, long long cost) {
    if (cost < best[u]) best[u] = cost;
    for (int v = 0; v < n; v++) {
        if (edge[u][v] == INF || visited[v]) continue;
        visited[v] = 1;
        dfs(v, cost + edge[u][v]);
