/*
 * Floyd：dist[i][j]表示当前允许使用的中间顶点集合下，i到j的最短距离。
 * 外层k逐个开放中间顶点；比较不经过k与经过k两种情况。
 * 允许负边，但题目保证没有负环；INF参与加法前必须先判可达。
 */
#include <stdio.h>
#include <limits.h>

#define MAXN 8
#define INF (LLONG_MAX / 4)

int main(void) {
    int n, m;
    long long dist[MAXN][MAXN];
    if (scanf("%d%d", &n, &m) != 2) return 1;

    // 初始化：自己到自己为0，其余顶点对暂时不可达。
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            dist[i][j] = (i == j ? 0 : INF);
        }
    }
    // 读入有向边，直接记录边权。
    for (int e = 0; e < m; e++) {
        int u, v;
        long long w;
        if (scanf("%d%d%lld", &u, &v, &w) != 3) return 1;
        dist[u - 1][v - 1] = w;
    }

    // k必须放在最外层：逐步允许顶点k作为路径中间点。
    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            if (dist[i][k] == INF) continue;
            for (int j = 0; j < n; j++) {
                if (dist[k][j] == INF) continue;
                long long through = dist[i][k] + dist[k][j];
                if (through < dist[i][j]) dist[i][j] = through;
            }
        }
    }

    // 输出距离矩阵；不可达统一输出-1。
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (dist[i][j] == INF) printf("-1");
            else printf("%lld", dist[i][j]);
            printf(j + 1 == n ? "\n" : " ");
        }
    }
    return 0;
}

