/*
 * 朴素层序遍历：先求树高，再对每一层分别递归扫描。
 * tree数组用下标表示左右孩子，-1表示空孩子。
 */
#include <stdio.h>

typedef struct {
    char data;
    int left;
    int right;
} Node;

int height(int u, const Node tree[]) {
    if (u == -1) return 0; // 空子树高度为0，不再访问不存在的结点
    int lh = height(tree[u].left, tree);
    int rh = height(tree[u].right, tree);
    return 1 + (lh > rh ? lh : rh);
}

void printLevel(int u, int level, const Node tree[]) {
    if (u == -1) return; // 空孩子不输出，也不继续递归
    if (level == 1) {
        printf("%c ", tree[u].data);
        return; // 已到目标层，当前分支完成，无须继续向下
    }
    printLevel(tree[u].left, level - 1, tree);
    printLevel(tree[u].right, level - 1, tree);
}

