/*
 * 朴素方案：一个数组固定分成左右两段，分别存放两个栈。
 * 栈1占[0, mid-1]，栈2占[mid, n-1]。
 */
#include <stdio.h>
#define MAXN 100

typedef struct {
    int data[MAXN];
    int n;
    int mid;
    int top1;  // 栈1为空时为-1
    int top2;  // 栈2为空时为mid-1
} FixedStacks;

void initFixed(FixedStacks *s, int n) {
    s->n = n;
    s->mid = n / 2;
    s->top1 = -1;
    s->top2 = s->mid - 1;
}

int push1(FixedStacks *s, int x) {
    if (s->top1 == s->mid - 1) return 0; // 左半区已满
    s->data[++s->top1] = x;
    return 1;
}

int push2(FixedStacks *s, int x) {
    if (s->top2 == s->n - 1) return 0;   // 右半区已满
    s->data[++s->top2] = x;
    return 1;
}

int pop1(FixedStacks *s, int *x) {
    if (s->top1 == -1) return 0;         // 栈1为空
    *x = s->data[s->top1--];
    return 1;
}

int pop2(FixedStacks *s, int *x) {
    if (s->top2 == s->mid - 1) return 0; // 栈2为空
    *x = s->data[s->top2--];
    return 1;
}

