    int n = 8;

    initFixed(&s, n);                    // 左右各分配4个位置

    push1(&s, 10);
    push1(&s, 20);
    push1(&s, 30);
    push1(&s, 40);                       // 栈1的4个位置全部占满
    push2(&s, 90);                       // 栈2只使用了右半区的第1个位置

    if (!push1(&s, 50))
        puts("固定分区：栈1溢出，但栈2一侧仍有空位");

    printf("top1=%d, top2=%d, mid=%d\n",
           s.top1, s.top2, s.mid);
    return 0;                            // 演示固定分区的空间浪费
}

optimal.code:
/*
 * 优化方案：两个栈从数组两端向中间生长，共享全部空闲单元。
 * 栈1入栈时top1右移；栈2入栈时top2左移。
 */
#include <stdio.h>
#define MAXN 100

typedef struct {
    int data[MAXN];
    int n;
    int top1;  // 栈1为空时为-1
    int top2;  // 栈2为空时为n
} SharedStacks;

void initShared(SharedStacks *s, int n) {
    s->n = n;
    s->top1 = -1;
    s->top2 = n;
}

int push1(SharedStacks *s, int x) {
    if (s->top1 + 1 == s->top2) return 0; // 两栈顶相邻，数组已满
    s->data[++s->top1] = x;
    return 1;
}

int push2(SharedStacks *s, int x) {
    if (s->top1 + 1 == s->top2) return 0; // 两栈顶相邻，数组已满
    s->data[--s->top2] = x;
    return 1;
}

int pop1(SharedStacks *s, int *x) {
    if (s->top1 == -1) return 0;           // 栈1为空
    *x = s->data[s->top1--];
    return 1;
}

int pop2(SharedStacks *s, int *x) {
    if (s->top2 == s->n) return 0;         // 栈2为空
    *x = s->data[s->top2++];
    return 1;
}

void showArray(const SharedStacks *s) {
    for (int i = 0; i < s->n; i++) {
        if (i > s->top1 && i < s->top2)
            printf("_ ");                  // 下划线表示尚未使用的位置
        else
            printf("%d", s->data[i]);
        if (i + 1 < s->n) putchar(' ');
    }
    putchar('\n');
}

int main(void) {
    SharedStacks s;
    int n = 8;

    initShared(&s, n);                     // 两栈分别从数组两端开始

    push1(&s, 10);
    push1(&s, 20);
    push1(&s, 30);
    push1(&s, 40);
    push2(&s, 90);
    push2(&s, 80);
    push2(&s, 70);                         // 两栈共占7个位置
    push1(&s, 50);                         // 使用最后一个空位，成功

    printf("数组：");
    showArray(&s);
    printf("top1=%d, top2=%d\n", s.top1, s.top2);

    if (!push2(&s, 60))
        puts("共享空间：两个栈顶相邻，整个数组已满");

    return 0;                              // 每个空闲位置都可被任一栈使用
}

