/*
 * 巩固题：按给定顺序执行两个共享栈的操作并输出出栈结果。
 */
#include <stdio.h>
#define MAXN 100

typedef struct {
    int data[MAXN];
    int n;
    int top1;
    int top2;
} SharedStacks;

void init(SharedStacks *s, int n) {
    s->n = n;
    s->top1 = -1;
    s->top2 = n;
}

int push1(SharedStacks *s, int x) {
    if (s->top1 + 1 == s->top2) return 0; // 两栈顶相邻，已没有可用单元
    s->data[++s->top1] = x;
    return 1;
}

int push2(SharedStacks *s, int x) {
    if (s->top1 + 1 == s->top2) return 0;
    s->data[--s->top2] = x;
    return 1;
}

int pop1(SharedStacks *s, int *x) {
    if (s->top1 == -1) return 0;           // 栈1为空，不能弹出
    *x = s->data[s->top1--];
    return 1;                              // 成功取出栈1栈顶
}

int pop2(SharedStacks *s, int *x) {
    if (s->top2 == s->n) return 0;         // 栈2为空，不能弹出
    *x = s->data[s->top2++];
    return 1;                              // 成功取出栈2栈顶
}

int main(void) {
    SharedStacks s;
    int x;

    init(&s, 6);                           // 两个栈共用6个位置
    push1(&s, 1);
    push2(&s, 9);
    push1(&s, 2);

    if (pop2(&s, &x)) printf("Pop2=%d\n", x); // 输出9
    push2(&s, 8);
    push1(&s, 3);

    if (pop1(&s, &x)) printf("Pop1=%d\n", x); // 输出3
    if (pop2(&s, &x)) printf("Pop2=%d\n", x); // 输出8

    printf("栈1自底向顶：");
    for (int i = 0; i <= s.top1; i++) {
        if (i > 0) putchar(' ');
        printf("%d", s.data[i]);
    }
    putchar('\n');

    printf("栈2为空：%s\n", s.top2 == s.n ? "是" : "否");
    return 0;                              // 最终栈1为[1,2]，栈2为空
}

brute.code:
/*
 * 朴素法：每个长度为k的窗口都从头扫描，找出最大元素。
 * 窗口之间会重复比较元素，最坏时间为O(nk)。
 */
#include <stdio.h>
#define MAXN 100000

int main(void) {
    int n, k, a[MAXN], answer[MAXN];

    if (scanf("%d%d", &n, &k) != 2) return 0; // 没有读到完整的n和k
    if (n < 1 || n > MAXN || k < 1 || k > n) {
        fprintf(stderr, "invalid n or k\n");
        return 1; // 窗口长度必须在数组长度范围内
    }
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1) return 1; // 输入元素不完整
    }

    int out = 0;
    for (int left = 0; left + k <= n; left++) {
        int maxIndex = left;
        for (int j = left + 1; j < left + k; j++) {
            if (a[j] > a[maxIndex])
                maxIndex = j; // 只有更大元素才替换当前最大值下标
        }
        answer[out++] = a[maxIndex];
    }

    for (int i = 0; i < out; i++)
        printf("%d%c", answer[i], i + 1 == out ? '\n' : ' ');
    return 0; // 所有窗口均已扫描并输出
}

optimal.code:
/*
 * 单调双端队列存储下标，队列对应的数值从队首到队尾严格递减。
 * 每个下标最多入队、出队各一次，因此总时间为O(n)。
 */
#include <stdio.h>
#define MAXN 100000

int main(void) {
    int n, k, a[MAXN], deque[MAXN], answer[MAXN];
    if (scanf("%d%d", &n, &k) != 2) return 0; // 没有读到完整的n和k
    if (n < 1 || n > MAXN || k < 1 || k > n) {
        fprintf(stderr, "invalid n or k\n");
        return 1; // 窗口长度必须在数组长度范围内
    }
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1) return 1; // 输入元素不完整
    }

    int head = 0, tail = 0, out = 0;
    for (int i = 0; i < n; i++) {
        // 队首下标不在当前窗口内，不能再作为最大值候选。
        while (head < tail && deque[head] <= i - k)
            head++;

        // 新元素更大或相等时，队尾旧元素以后不可能成为最大值。
        while (head < tail && a[deque[tail - 1]] <= a[i])
            tail--;

        deque[tail++] = i; // 保存下标，才能判断元素何时滑出窗口
        if (i >= k - 1)
            answer[out++] = a[deque[head]]; // 队首就是当前窗口最大值
    }

    for (int i = 0; i < out; i++)
        printf("%d%c", answer[i], i + 1 == out ? '\n' : ' ');
    return 0; // 每个完整窗口都已输出
}

variation.code:
/*
 * 变式：使用最大堆保存(数值,下标)，堆顶始终是当前最大候选。
 * 过期元素采用惰性删除：只有到达堆顶时才弹出。
 */
#include <stdio.h>
#define MAXN 100000

typedef struct {
    int value;
    int index;
} Item;

Item heap[MAXN];
int heapSize = 0;

int higher(Item a, Item b) {
    if (a.value != b.value) return a.value > b.value;
    return a.index > b.index; // 数值相同优先保留较新的下标
}

void push(Item x) {
    int i = heapSize++;
    while (i > 0) {
        int parent = (i - 1) / 2;
        if (!higher(x, heap[parent])) break;
        heap[i] = heap[parent];
        i = parent;
    }
    heap[i] = x;
}

Item popMax(void) {
    Item result = heap[0];
    Item last = heap[--heapSize];
    int i = 0;

    while (i * 2 + 1 < heapSize) {
        int child = i * 2 + 1;
        if (child + 1 < heapSize && higher(heap[child + 1], heap[child]))
            child++;
        if (!higher(heap[child], last)) break;
        heap[i] = heap[child];
        i = child;
    }
    if (heapSize > 0) heap[i] = last;
    return result; // 返回原堆顶，供调用者检查是否过期
}

int main(void) {
    int n, k, a[MAXN], answer[MAXN];
    if (scanf("%d%d", &n, &k) != 2) return 0; // 没有读到完整的n和k
    if (n < 1 || n > MAXN || k < 1 || k > n) {
        fprintf(stderr, "invalid n or k\n");
        return 1; // 窗口长度必须在数组长度范围内
    }
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1) return 1; // 输入元素不完整
    }

    int out = 0;
    for (int i = 0; i < n; i++) {
        Item x = {a[i], i};
        push(x);
        // 堆顶若已滑出窗口就删除；循环处理连续的过期堆顶。
        while (heapSize > 0 && heap[0].index <= i - k)
            (void)popMax();
        if (i >= k - 1)
            answer[out++] = heap[0].value;
    }

    for (int i = 0; i < out; i++)
        printf("%d%c", answer[i], i + 1 == out ? '\n' : ' ');
    return 0; // 所有完整窗口的最大值均已输出
}
